	 (3071,'alpha_vantage','TGT','TGT','2026-02-09 23:29:02','20260209T232902','Target to test ads on ChatGPT this month','https://breakingthenews.net/Article/Target-to-test-ads-on-ChatGPT-this-month/65634487','Target is planning to test placing advertisements on the ChatGPT platform this month. This initiative marks a new venture for the retail giant into AI-driven advertising spaces.',NULL,'Breaking The News','General','Breaking The News','[{"topic": "retail_wholesale", "relevance_score": "0.726043"}, {"topic": "technology", "relevance_score": "0.805739"}]',0.110358,'Neutral','[{"ticker": "TGT", "relevance_score": "1.000000", "ticker_sentiment_label": "Neutral", "ticker_sentiment_score": "0.119238"}]','{"url": "https://breakingthenews.net/Article/Target-to-test-ads-on-ChatGPT-this-month/65634487", "title": "Target to test ads on ChatGPT this month", "source": "Breaking The News", "topics": [{"topic": "retail_wholesale", "relevance_score": "0.726043"}, {"topic": "technology", "relevance_score": "0.805739"}], "authors": [], "summary": "Target is planning to test placing advertisements on the ChatGPT platform this month. This initiative marks a new venture for the retail giant into AI-driven advertising spaces.", "banner_image": null, "source_domain": "Breaking The News", "time_published": "20260209T232902", "ticker_sentiment": [{"ticker": "TGT", "relevance_score": "1.000000", "ticker_sentiment_label": "Neutral", "ticker_sentiment_score": "0.119238"}], "category_within_source": "General", "overall_sentiment_label": "Neutral", "overall_sentiment_score": 0.110358}','2026-02-10 17:21:55',NULL);
